parameters.functionCode:
// PROCESADOR TELEGRAM - FASE 2 CONVERSACIONAL
const update = $json.body || $json;
const msg = update.message;
const cbq = update.callback_query;

if (!msg && !cbq) {
  return [];
}

const text = (msg && msg.text ? msg.text : '').trim();
const chatId = (msg && msg.chat && msg.chat.id) || (cbq && cbq.message && cbq.message.chat && cbq.message.chat.id);
const from = (msg && msg.from) ? msg.from : (cbq && cbq.from ? cbq.from : {});
const userId = from.id;
const username = from.username || from.first_name || 'user';

const command = text.startsWith('/') ? text.split(' ')[0].toLowerCase() : null;

// Comandos principales - AL ROUTER
if (command === '/start' || command === '/help') {
  return [{ json: { action: 'start_wizard', telegramData: { chatId: chatId, userId: userId, username: username }, session: { chatId: chatId } } }];
}

// Login - AL ROUTER
if (command === '/login') {
  return [{ json: { action: 'login_init', telegramData: { chatId: chatId, userId: userId, username: username } } }];
}

// Cancelar - AL ROUTER
if (command === '/cancel' || command === '/logout') {
  return [{ json: { action: 'cancel', telegramData: { chatId: chatId, userId: userId, username: username }, session: { chatId: chatId } } }];
}

// Entrada rápida - AL ROUTER
if (command === '/entrada' || /entrada/i.test(text)) {
  return [{ json: { action: 'start_wizard', movementType: 'ENTRADA', telegramData: { chatId: chatId, userId: userId, username: username }, session: { chatId: chatId, type: 'ENTRADA' } } }];
}

// Salida rápida - AL ROUTER
if (command === '/salida' || /salida/i.test(text)) {
  return [{ json: { action: 'start_wizard', movementType: 'SALIDA', telegramData: { chatId: chatId, userId: userId, username: username }, session: { chatId: chatId, type: 'SALIDA' } } }];
}

// Callbacks de botones - AL ROUTER
if (cbq && cbq.data) {
  return [{ json: { action: 'continue', telegramData: { chatId: chatId, userId: userId, username: username }, session: { chatId: chatId }, input: { callback: cbq.data } } }];
}

// Texto - AL ROUTER
if (text) {
  return [{ json: { action: 'continue', telegramData: { chatId: chatId, userId: userId, username: username }, session: { chatId: chatId }, input: { text: text } } }];
}

// Default - DIRECTO A TELEGRAM
return [{ json: { action: 'send_message', chatId: chatId, message: 'No entendí. Usa /start para ver el menú principal.' } }];

parameters.jsonBody:
={{ (function(){
  const chatId = $json.chatId || ($json.telegramData && $json.telegramData.chatId) || $json.chat_id;
  const message = $json.message || $json.text;

  const b = {
    chat_id: chatId,
    text: message,
    parse_mode: 'Markdown'
  };

  if ($json.reply_markup) {
    b.reply_markup = $json.reply_markup;
  }

  return b;
})() }}

={{ ({
  action: $json.action,
  telegramData: ($json.telegramData || { chatId: $json.chatId }),
  session: ($json.session || { chatId: $json.chatId }),
  input: ($json.input || {}),
  movementType: $json.movementType
}) }}
